// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "Token", "TKN"); }

    function testFuzz_property(address target, uint256 burnAmount) public {
        vm.assume(target != address(this));
        vm.assume(burnAmount > 0 && burnAmount <= 1000 * 10**uint256(c.decimals()));

        bool frozenBefore = c.frozenAccount(target);

        c.freezeAccount(target, true);

        c.burn(burnAmount);

        bool frozenAfter = c.frozenAccount(target);

        assertTrue(frozenAfter == true);
    }
}
